  "Strongly recommended for administrators.": ["Sterk aanbeveel vir administrateurs.", "Go šišinywa kudu bakeng sa balaodi.", "Swi tsundzuxiwa ngopfu eka valawuri.", "Kunconywa kakhulu kubaphathi."],
  "Summary": ["Opsomming", "Kakaretšo", "Nkatsakanyo", "Isifinyezo"],
  "Supplier": ["Verskaffer", "Mofepi", "Muphakeri", "Umhlinzeki"],
